"""Small text helpers."""

import re


def word_count(text: str) -> int:
    """The number of words in ``text``."""
    return len(text.split())


def slugify(text: str) -> str:
    """``text`` as a lowercase slug for a web address."""
    slug = re.sub(r"[^a-z0-9]+", "-", text.lower()).strip("-")
    return slug[:40].rstrip("-")
